def _same_dataset(a: str, b: str) -> bool:
    """Loose but non-vacuous dataset identity check.

    Provenance strings in this repo are free text
    ('CICIDS2017_improved/monday benign-only'), and callers pass a description
    ('original CIC-IDS2017 PortScan'). Rather than require an exact match, treat
    the two as the same when one contains the other, or when they share a
    recognisable dataset token. Anything else counts as different.
    """
    na, nb = a.lower().strip(), b.lower().strip()
    if na in nb or nb in na:
        return True
    tokens = {
        "original": "cic-ids2017", "orig": "cic-ids2017", "cic-ids2017": "cic-ids2017",
        "cicids2017": "cic-ids2017", "improved": "improved", "cns2022": "improved",
        "adfa": "adfa", "adfa-ld": "adfa",
    }
    da = {tokens[t] for t in re.findall(r"[a-z0-9\-]+", na) if t in tokens}
    db = {tokens[t] for t in re.findall(r"[a-z0-9\-]+", nb) if t in tokens}
    return bool(da & db)

